-- SELECT only. 20261128120000_mcp_claude_attach 적용 전(시험 적용 전후 비교에도 씀). 카탈로그·migration 기록만 읽는다(행 값 없음).
-- 기대: 예/아니오 항목은 모두 예. 해시는 기록만 하고 사후 확인에서 같은 값이어야 한다(바꾸지 않는 MCP 함수·노트·설정·기록 표의 권한·정책·트리거가 그대로라는 뜻).
-- expect: new migration absent = 예
-- expect: write migration applied = 예
-- expect: write gate and undo first edition = 예
-- expect: attach objects absent = 예
-- expect: note columns present = 예
-- expect: existing boundary hash = 기록
select 'new migration absent' as item,case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261128120000') then '예' else '아니오' end as value
union all select 'write migration applied',case when (select count(*) from supabase_migrations.schema_migrations where version='20261128100000' and name='mcp_claude_write')=1 and to_regclass('public.app_mcp_write_log') is not null then '예' else '아니오' end
union all select 'write gate and undo first edition',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_mcp_write_gate(text)') and prosecdef) and to_regprocedure('public.app_mcp_write_undo(uuid)') is not null and pg_get_functiondef(to_regprocedure('private.app_mcp_write_gate(text)')) not like '%web2_attach%' and pg_get_functiondef(to_regprocedure('public.app_mcp_write_undo(uuid)')) not like '%attach%' then '예' else '아니오' end
union all select 'attach objects absent',case when not exists(select 1 from pg_attribute a where a.attrelid=to_regclass('public.app_mcp_write_log') and a.attname in ('files','file_bytes') and not a.attisdropped) and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname in ('app_mcp_attach_check','app_mcp_attach_commit','app_mcp_attach_undone')) then '예' else '아니오' end
union all select 'note columns present',case when (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_notes') and a.attname in ('attachments','kind','deleted_at','updated_at','workspace_id','metadata','ai_export_allowed') and not a.attisdropped)=7 then '예' else '아니오' end
union all select 'existing boundary hash',md5(coalesce((select string_agg(p.oid::regprocedure::text||md5(pg_get_functiondef(p.oid))||coalesce(p.proacl::text,''),',' order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname in('public','private') and p.proname like 'app\_mcp\_%' and p.proname not in ('app_mcp_write_gate','app_mcp_write_undo','app_mcp_attach_check','app_mcp_attach_commit','app_mcp_attach_undone')) or p.oid in (to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('private.app_is_workspace_owner(uuid)'))),'')||coalesce((select string_agg(c.relname::text||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in (to_regclass('public.app_notes'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before'),to_regclass('public.app_operator_features'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(p.polrelid::regclass::text||p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polrelid::regclass::text,p.polname) from pg_policy p where p.polrelid in (to_regclass('public.app_notes'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before'),to_regclass('public.app_operator_features'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(t.tgrelid::regclass::text||t.tgname::text||t.tgenabled::text,',' order by t.tgrelid::regclass::text,t.tgname) from pg_trigger t where not t.tgisinternal and t.tgrelid in (to_regclass('public.app_notes'),to_regclass('public.app_mcp_write_log'))),''));
